contracts.binding_program:
def apply(inputs, premises):
    public = inputs.get('public_case', {})
    facts = public.get('facts')
    question = public.get('question')
    context = inputs.get('literal_context', {})
    values = context.get('values', {}) if type(context) is dict else {}
    observation = inputs.get('observation')
    unresolved = []
    employer = values.get('employer')
    employee = values.get('employee')
    if (type(employer) is not str or type(employee) is not str) and type(observation) is dict:
        roles = observation.get('task_roles', {})
        if roles.get('status') == 'known':
            employer = roles.get('employer')
            employee = roles.get('employee')
    if type(employer) is not str or type(employee) is not str or employer == employee:
        return {'bindings': [], 'unresolved': ['employer_and_employee_roles_unresolved']}
    service_values = []
    if type(values.get('employer')) is str and type(values.get('employee')) is str:
        service_values.append(True)
    if type(observation) is dict:
        service = observation.get('service', {})
        if service.get('status') == 'known' and type(service.get('value')) is bool and service.get('value') not in service_values:
            service_values.append(service.get('value'))
    if len(service_values) == 0:
        unresolved.append('service_performed_in_employ_unresolved')
    mentions = []
    literal_mentions = values.get('case_family_relations')
    literal_relation_found = False
    if type(literal_mentions) is list:
        for row in literal_mentions:
            if type(row) is list and len(row) == 3:
                mentions.append(row)
                literal_relation_found = True
    if type(observation) is dict:
        observed_mentions = observation.get('family_mentions')
        if type(observed_mentions) is list:
            for row in observed_mentions:
                if type(row) is dict:
                    mentions.append([row.get('owner'), row.get('relation'), row.get('relative')])
        if not literal_relation_found and observation.get('family_mentions_extraction_status') != 'resolved':
            unresolved.append('family_relation_extraction_unresolved')
    relationships = []
    unsupported_reverse = False
    for row in mentions:
        owner = row[0]
        relation = row[1]
        relative = row[2]
        if type(owner) is not str or type(relation) is not str or type(relative) is not str:
            continue
        relation = relation.casefold()
        projected = []
        if owner == employee and relative == employer:
            if relation in ('wife', 'husband'):
                projected.append('spouse')
            else:
                projected.append(relation)
        elif owner == employer and relative == employee:
            if relation in ('father', 'mother'):
                projected.extend(['son', 'daughter'])
            elif relation in ('son', 'daughter'):
                projected.extend(['father', 'mother'])
            elif relation in ('spouse', 'wife', 'husband'):
                projected.append('spouse')
            else:
                unsupported_reverse = True
        for value in projected:
            if value not in relationships:
                relationships.append(value)
    if unsupported_reverse:
        unresolved.append('inverse_of_observed_kinship_word_unresolved')
    if len(relationships) == 0:
        unresolved.append('employer_relationship_to_employee_unresolved')
    witnesses = []
    if type(facts) is str and facts:
        witnesses.append({'field': 'facts', 'quote': facts})
    if type(question) is str and question:
        witnesses.append({'field': 'question', 'quote': question})
    if len(witnesses) == 0:
        return {'bindings': [], 'unresolved': unresolved + ['current_case_witness_unavailable']}
    bindings = []
    if len(service_values) > 0 and len(relationships) > 0:
        for relationship in relationships:
            for service_value in service_values:
                bindings.append({'inputs': {'service_performed_in_employ': service_value, 'employer_relationship_to_employee': relationship}, 'witnesses': list(witnesses)})
    return {'bindings': bindings, 'unresolved': unresolved}

def apply(inputs, premises):
    observation = inputs.get('observation')
    if type(observation) is not dict:
        return {'bindings': [], 'unresolved': ['payment_event_observation_required']}
    claimant_record = observation.get('claimant', {})
    year_record = observation.get('query_year', {})
    unresolved = []
    if claimant_record.get('status') != 'known' or type(claimant_record.get('value')) is not str:
        unresolved.append('claimant_unresolved')
    if year_record.get('status') != 'known' or type(year_record.get('value')) is not int:
        unresolved.append('query_year_unresolved')
    events = observation.get('payment_events')
    status = observation.get('payment_events_extraction_status')
    if type(events) is not list or status not in ('resolved', 'unknown', 'failed'):
        unresolved.append('payment_event_record_invalid')
    if len(unresolved) > 0:
        return {'bindings': [], 'unresolved': unresolved}
    payment_events = []
    witnesses = []
    for witness in claimant_record.get('witnesses', []):
        if witness not in witnesses:
            witnesses.append(witness)
    for witness in year_record.get('witnesses', []):
        if witness not in witnesses:
            witnesses.append(witness)
    for event in events:
        row = {'payer': event.get('payer'), 'payee': event.get('payee'), 'stated_labor': event.get('stated_labor'), 'amount': event.get('amount'), 'period_start': event.get('period_start'), 'period_end': event.get('period_end'), 'wages_given': event.get('wages_given')}
        payment_events.append(row)
        for witness in event.get('witnesses', []):
            if witness not in witnesses:
                witnesses.append(witness)
    if len(witnesses) == 0:
        return {'bindings': [], 'unresolved': ['current_case_witness_unavailable']}
    binding = {'claimant': claimant_record.get('value'), 'query_year': year_record.get('value'), 'payment_events': payment_events, 'payment_events_extraction_status': status}
    return {'bindings': [{'inputs': binding, 'witnesses': witnesses}], 'unresolved': []}

